contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We will call getFirstWithdrawalBonus on some target recipient address 'r'.
    // The test observes contract balance before and after and asserts it never increased.
    function run(address r) public payable {
        require(r != address(0));

        uint balBefore = address(c).balance;

        bool reverted;
        c.getFirstWithdrawalBonus(r); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfter = address(c).balance;

        // General rule: the contract's balance must not increase as a result of the call
        // (it may stay the same or decrease). This asserts for all inputs r.
        assert(balAfter <= balBefore);
    }

    receive() external payable { }
}

